    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collActoadminDevolucions) {
                foreach ($this->collActoadminDevolucions as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collActoadministrativoUsuarios) {
                foreach ($this->collActoadministrativoUsuarios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collActoadministrativoServicios) {
                foreach ($this->collActoadministrativoServicios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collActoadministraInteresados) {
                foreach ($this->collActoadministraInteresados as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTransferencias) {
                foreach ($this->collTransferencias as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aDependencia instanceof Persistent) {
              $this->aDependencia->clearAllReferences($deep);
            }
            if ($this->aRegional instanceof Persistent) {
              $this->aRegional->clearAllReferences($deep);
            }
            if ($this->aPlantillasCom instanceof Persistent) {
              $this->aPlantillasCom->clearAllReferences($deep);
            }
            if ($this->aPrioridadCom instanceof Persistent) {
              $this->aPrioridadCom->clearAllReferences($deep);
            }
            if ($this->aTipoProcesoCom instanceof Persistent) {
              $this->aTipoProcesoCom->clearAllReferences($deep);
            }
            if ($this->aPeriodo instanceof Persistent) {
              $this->aPeriodo->clearAllReferences($deep);
            }
            if ($this->aEstadoActoAdministrativo instanceof Persistent) {
              $this->aEstadoActoAdministrativo->clearAllReferences($deep);
            }
            if ($this->aEstadoDigitalizacion instanceof Persistent) {
              $this->aEstadoDigitalizacion->clearAllReferences($deep);
            }
            if ($this->aSubserie instanceof Persistent) {
              $this->aSubserie->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collActoadminDevolucions instanceof PropelCollection) {
            $this->collActoadminDevolucions->clearIterator();
        }
        $this->collActoadminDevolucions = null;
        if ($this->collActoadministrativoUsuarios instanceof PropelCollection) {
            $this->collActoadministrativoUsuarios->clearIterator();
        }
        $this->collActoadministrativoUsuarios = null;
        if ($this->collActoadministrativoServicios instanceof PropelCollection) {
            $this->collActoadministrativoServicios->clearIterator();
        }
        $this->collActoadministrativoServicios = null;
        if ($this->collActoadministraInteresados instanceof PropelCollection) {
            $this->collActoadministraInteresados->clearIterator();
        }
        $this->collActoadministraInteresados = null;
        if ($this->collTransferencias instanceof PropelCollection) {
            $this->collTransferencias->clearIterator();
        }
        $this->collTransferencias = null;
        $this->aDependencia = null;
        $this->aRegional = null;
        $this->aPlantillasCom = null;
        $this->aPrioridadCom = null;
        $this->aTipoProcesoCom = null;
        $this->aPeriodo = null;
        $this->aEstadoActoAdministrativo = null;
        $this->aEstadoDigitalizacion = null;
        $this->aSubserie = null;
